#include <array>
#include <iostream>
#include <utility>
#include <vector>

using Integer = long long;
constexpr int PRIME_COUNT = 35;
constexpr int PRIME_BITS = 29;
constexpr int ROW_BOUND_BITS = 10;
// the 35 smallest primes above 10^9, between 2^29 and 2^30; generated by 1914_matrix_table.py
constexpr std::array<Integer, PRIME_COUNT> PRIMES = {
    1000000007, 1000000009, 1000000021, 1000000033, 1000000087, 1000000093, 1000000097,
    1000000103, 1000000123, 1000000181, 1000000207, 1000000223, 1000000241, 1000000271,
    1000000289, 1000000297, 1000000321, 1000000349, 1000000363, 1000000403, 1000000409,
    1000000411, 1000000427, 1000000433, 1000000439, 1000000447, 1000000453, 1000000459,
    1000000483, 1000000513, 1000000531, 1000000579, 1000000607, 1000000613, 1000000637};

Integer power(Integer value, Integer exponent, Integer modulus) {
    Integer result = 1;
    while (exponent > 0) {
        if (exponent & 1) {
            result = result * value % modulus;
        }
        value = value * value % modulus;
        exponent >>= 1;
    }
    return result;
}

Integer determinantModulo(const std::vector<std::vector<Integer>> &matrix, Integer modulus) {
    auto values = matrix;
    const int size = int(values.size());
    for (auto &row : values) {
        for (Integer &value : row) {
            value = (value % modulus + modulus) % modulus;
        }
    }
    Integer determinant = 1;
    for (int column = 0; column < size; ++column) {
        int pivot = column;
        while (pivot < size && values[pivot][column] == 0) {
            ++pivot;
        }
        if (pivot == size) {
            return 0;
        }
        if (pivot != column) {
            std::swap(values[pivot], values[column]);
            determinant = modulus - determinant;
        }
        const auto &pivotLine = values[column];
        const Integer pivotValue = pivotLine[column];
        determinant = determinant * pivotValue % modulus;
        const Integer inverse = power(pivotValue, modulus - 2, modulus);
        for (int row = column + 1; row < size; ++row) {
            auto &line = values[row];
            if (line[column] == 0) {
                continue;
            }
            const Integer factor = line[column] * inverse % modulus;
            for (int target = column + 1; target < size; ++target) {
                Integer value = line[target] - factor * pivotLine[target] % modulus;
                if (value < 0) {
                    value += modulus;
                }
                line[target] = value;
            }
            line[column] = 0;
        }
    }
    return determinant;
}

bool isUnimodular(const std::vector<std::vector<Integer>> &matrix) {
    const int needed = (ROW_BOUND_BITS * int(matrix.size()) + PRIME_BITS) / PRIME_BITS;
    int sign = 0;
    for (int index = 0; index < needed; ++index) {
        const Integer modulus = PRIMES[index];
        const Integer determinant = determinantModulo(matrix, modulus);
        const int current = determinant == 1 ? 1 : determinant == modulus - 1 ? -1 : 0;
        if (current == 0 || (sign != 0 && sign != current)) {
            return false;
        }
        sign = current;
    }
    return true;
}

int main() {
    std::ios::sync_with_stdio(false);
    std::cin.tie(nullptr);
    int size;
    std::cin >> size;
    std::vector<std::vector<Integer>> matrix(size, std::vector<Integer>(size));
    for (auto &row : matrix) {
        for (Integer &value : row) {
            std::cin >> value;
        }
    }
    std::cout << (isUnimodular(matrix) ? "Death\n" : "Power of magic saves lives\n");
    return 0;
}
